# -*- coding: utf-8 -*-
"""Phase 02: 정렬 (weeks 14–26)."""
from curriculum.common import A, phase
from curriculum.al.resources import R_EARLY as R

PHASE = phase("정렬", 14, 26, "정렬", "스택", "삽입·선택·병합·퀵 정렬과 계수 정렬을 구현하고 점근 표기 입문으로 비교 횟수를 판별한다. 마스터 정리는 아직 쓰지 않는다.", R, [
A("삽입 정렬", "앞쪽", "제자리", "삽입 정렬은 앞부분이 이미 정렬되어 있다고 보고, 다음 값을 그 안의 알맞은 위치에 끼워 넣는다.", "[3, 1, 2]에서 1을 맨 앞에 끼우면 [1, 3, 2]이고, 이어서 2를 끼우면 [1, 2, 3]이다.", "다음 값을 항상 맨 앞에 붙이면 정렬이 아니라 순서를 뒤집는 것이 된다.", "'앞부분은 정렬되어 있다'는 문장이 루프 불변식이다. 증명은 나중에 하고 지금은 표로 확인한다."),
A("선택 정렬과 비교", "최솟값", "교환", "선택 정렬은 남은 구간에서 최솟값을 골라 그 구간의 맨 앞 값과 바꾼다. 삽입 정렬과는 교환이 일어나는 방식이 다르다.", "[3, 1, 2]에서 1과 3을 바꿔 [1, 3, 2]가 되고, 이어서 2와 3을 바꿔 [1, 2, 3]이 된다.", "고른 최솟값을 맞바꾸지 않고 복사만 하면 같은 값이 두 번 생긴다.", "두 정렬 모두 반복문 안에 반복문이 있어서 비교 횟수가 n×n에 가깝다. 병합 정렬은 따로 센다."),
A("앞쪽은 정렬", "불변", "i칸", "i번째 단계 전에는 앞의 i칸이 정렬되어 있다. 그 시점에 배열 전체가 정렬되어 있을 필요는 없다.", "[3, 1, 2]에서 1을 끼운 직후 앞의 두 칸은 [1, 3]이다. 마지막 2는 아직 정렬된 부분 밖에 있다.", "'배열 전체가 항상 정렬되어 있다'고 쓰면 중간 상태 [1, 3, 2]가 반례가 된다.", "불변식이 다루는 범위는 앞부분이지 배열 전체가 아니다."),
A("정렬의 안정", "같은 값", "순서", "정렬이 끝난 뒤에도 같은 값끼리 원래 순서가 그대로 남으면 안정 정렬이다. 삽입 정렬은 자기보다 큰 값만 뒤로 밀기 때문에 같은 값의 순서가 바뀌지 않는다.", "(3,a), (1,b), (3,c)를 삽입 정렬하면 두 3 가운데 a가 c보다 앞에 온다.", "같은 3을 만날 때마다 무조건 자리를 바꾸면 c가 a보다 앞으로 온다.", "안정성은 값이 아니라 같은 값에 붙은 이름의 순서를 지키는 성질이다."),
A("병합 정렬 구현", "반", "합치기", "목록을 반으로 나눠 각각 정렬한 뒤, 두 목록의 앞에서부터 작은 값을 골라 합친다. 한 칸이나 빈 목록이 더 나누지 않는 기저 사례다.", "[4, 1, 3, 2]는 [4, 1]과 [3, 2]로 나뉘고, 각각 [1, 4]와 [2, 3]이 된 뒤 합쳐져 [1, 2, 3, 4]가 된다.", "한 칸짜리 목록을 또 반으로 나누거나 합칠 때 오른쪽 남은 값을 버리면 멈추지 않거나 원소가 사라진다.", "나누기는 기저 사례에서 멈추고, 합치기는 두 목록의 앞 값을 비교한다. 둘 다 있어야 정렬이 완성된다."),
A("병합의 단계", "그림", "원소", "크기 8인 목록을 나누는 그림을 그리고, 합치기 단계마다 모든 원소가 한 번씩 쓰이는지 센다.", "8개는 4+4로, 다시 2+2 두 쌍으로, 다시 1+1 네 쌍으로 나뉜다. 되돌아오면서 합친다.", "나누는 그림만 그리고 합치기를 빼먹으면 정렬 결과가 나오지 않는다.", "단계 수는 8을 1이 될 때까지 반으로 나눈 횟수다. 지금은 그림으로만 센다."),
A("점근 표기 입문", "상한과 하한", "차수", "입력 크기 n이 커질 때 연산 횟수의 증가율을 O(상한), Ω(하한), Θ(정확 차수)로 구분한다. 작은 상수와 낮은 차수 항은 버린다.", "길이 8과 16에서 삽입 정렬은 n^2 꼴로 4배 가까이 늘고, 병합 정렬은 층 수 × n이라 2배 남짓 늘어난다. 3n^2+5n은 Θ(n^2)이다.", "상수 계수만 보고 2n^2이 n log n보다 항상 빠르다고 쓰면 n이 커질 때 증가 차수가 뒤집히는 지점을 놓친다.", "점근 표기는 기계 속도가 아니라 입력 크기가 커질 때 알고리즘의 성장 차수를 비교하는 공통 언어다."),
A("합치기의 두 칸", "왼쪽", "오른쪽", "정렬된 두 목록의 맨 앞 값만 비교해 더 작은 쪽을 결과에 붙이고, 그 목록의 위치만 한 칸 앞으로 옮긴다.", "[1, 4]와 [2, 3]에서 1을 붙인 뒤 4와 2를 비교해 2를 붙인다. 이어서 4와 3을 비교해 3을 붙이고, 마지막으로 남은 4를 붙인다.", "비교에서 진 쪽의 위치까지 같이 옮기면 그 값이 결과에서 빠진다.", "합치기는 두 목록의 맨 앞 값만 본다. 이미 지나간 값은 다시 보지 않는다."),
A("역순의 개수", "왼쪽이 큼", "남음", "합칠 때 오른쪽 값이 왼쪽 값보다 작으면, 왼쪽에 남아 있는 값은 모두 그 오른쪽 값과 역순 쌍을 이룬다.", "[3, 1, 2]를 [3]과 [1, 2]로 나눈다. 1이 3보다 먼저 결과에 들어가면 역순이 하나, 2도 3보다 작아 하나 더 생긴다. 합은 2다.", "오른쪽 값 하나당 1개씩만 세고 왼쪽에 남은 개수를 더하지 않으면 3과 2의 역순이 빠진다.", "역순 개수는 정렬하면서 함께 세는 값이다. 따로 다시 정렬하지 않는다."),
A("퀵 정렬과 분할", "피벗", "분할", "피벗 값 하나를 골라 그보다 작거나 같은 값은 왼쪽, 큰 값은 오른쪽으로 모은 뒤 양쪽 구간을 재귀로 정렬한다. 추가 배열 없이 제자리에서 나눌 수 있다.", "[3, 1, 4, 2]에서 끝 값 2를 피벗으로 삼으면 [1, 2, 4, 3]으로 분할되어 2의 자리가 확정된다.", "이미 정렬된 배열에서 매번 맨 끝 값을 피벗으로 고르면 한쪽이 n-1칸 남아 비교가 n^2에 가까워진다.", "병합 정렬이 합치기에 일을 쏟는다면, 퀵 정렬은 분할에서 피벗 자리를 확정하는 데 일을 쏟는다."),
A("정렬의 비교", "n제곱", "추가 메모리", "삽입·선택 정렬은 O(n^2)이고 제자리에서 돈다. 병합 정렬은 항상 O(n log n)이지만 추가 배열이 필요하고, 퀵 정렬은 평균 O(n log n) 제자리이지만 최악 O(n^2)이 될 수 있다.", "길이 8을 삽입 정렬하면 이미 정렬된 입력에선 비교 7번에 끝나지만 역순에선 28번이다. 병합 정렬은 층 3개마다 원소 8개를 보고 추가 배열 길이 8을 쓴다.", "한 가지 기준(예: 최악 시간만, 또는 이미 정렬된 입력만)으로 한 정렬이 무조건 우월하다고 말하면 추가 메모리와 최악 조건을 빠뜨린 것이다.", "정렬 알고리즘 선택은 시간 차수, 최악 보장, 추가 메모리, 안정성의 네 축을 나란히 놓고 고르는 일이다."),
A("계수 정렬", "빈도표", "비교 없음", "원소가 0 이상 k 이하의 작은 정수라면 두 값을 직접 비교하지 않고 값별 빈도표를 세어 O(n+k) 시간에 안정 정렬한다.", "[3, 1, 3, 0]에서 빈도 배열 [1, 1, 0, 2]와 누적 합 [1, 2, 2, 4]를 뒤에서부터 채우면 같은 3의 원래 순서까지 보존된다.", "값의 범위 k가 n보다 훨씬 큰데(예: 10억) 계수 정렬을 쓰면 빈도 배열 메모리와 초기화 비용이 폭증한다.", "비교 기반 정렬이 아닌 정수 범위 제약 모델에서는 O(n+k) 선형 시간이 가능하며, 뒤의 기수 정렬과 비교 하한의 기초다."),
A("정렬 점검", "표", "모델", "[3, 1, 2]를 삽입·선택·병합·퀵·계수 정렬로 추적해 모두 [1, 2, 3]이 나오는지 확인하고, 각 정렬의 점근 상한·안정성·추가 배열 여부를 표로 적는다.", "[3, 1, 2]를 다섯 정렬로 추적한 결과는 모두 같고, 병합 정렬로 센 역순 개수는 2, 계수 정렬의 빈도표 길이는 4다.", "최종 결과만 비교하고 점근 차수(O)나 추가 메모리, 피벗 최악 조건을 비우면 점검이 아니다.", "다섯 정렬의 차이는 출력이 아니라 비교 방식, 점근 차수, 추가 배열, 안정성 조건에 있다."),
])
